		{999_500_000, 3, GByte, "1.00 GB"},
		{999_499_999_999, 3, 0, "999 GB"},
		{999_500_000_000, 3, TByte, "1.00 TB"},
		{999_499_999_999_999, 3, 0, "999 TB"},
		{999_500_000_000_000, 3, PByte, "1.00 PB"},
		// Above 2^53 float64(s) rounds: this threshold is measured.
		{999_499_999_999_999_935, 3, 0, "999 PB"},
		{999_499_999_999_999_936, 3, EByte, "1.00 EB"},

		{999_949, 4, 0, "999.9 kB"},
		{999_950, 4, MByte, "1.000 MB"},
		{999_949_999, 4, 0, "999.9 MB"},
		{999_950_000, 4, GByte, "1.000 GB"},
		{999_949_999_999, 4, 0, "999.9 GB"},
		{999_950_000_000, 4, TByte, "1.000 TB"},
		{999_949_999_999_999, 4, 0, "999.9 TB"},
		{999_950_000_000_000, 4, PByte, "1.000 PB"},
		// Above 2^53 float64(s) rounds: this threshold is measured.
		{999_949_999_999_999_935, 4, 0, "999.9 PB"},
		{999_949_999_999_999_936, 4, EByte, "1.000 EB"},

		{999_500, 0, MByte, "1 MB"},
		{999_500, 1, MByte, "1 MB"},
		{999_500, 2, MByte, "1.0 MB"},
		{999_500, -1, MByte, "1 MB"},
		{999_999, 0, MByte, "1 MB"},
		{999_999, 8, 0, "999.99900 kB"},
		{9, 3, 0, "9 B"},
	}
	for _, c := range cases {
		got := BytesN(c.in, c.n)
		if got != c.want {
			t.Errorf("BytesN(%d, %d): got %s, want %s", c.in, c.n, got, c.want)
		}
		if c.next != 0 {
			if unit := BytesN(c.next, c.n); got != unit {
