			t.Errorf("Bytes(%d): %v", c.in, err)
		}
	}
}

func TestIBytesUnitPromotion(t *testing.T) {
	cases := []struct {
		in   uint64
		n    int // 0: IBytes, otherwise IBytesN with this n
		want string
	}{
		{9, 0, "9 B"},
		{1023, 0, "1023 B"},
		{1024, 0, "1.0 KiB"},
		{1000 * 1024, 0, "1000 KiB"},
		{1023 * 1024, 0, "1023 KiB"},
		{1023.5*KiByte - 1, 0, "1023 KiB"},
		{1023.5 * KiByte, 0, "1.0 MiB"},
		{1_048_575, 0, "1.0 MiB"},
		{1023.5*MiByte - 1, 0, "1023 MiB"},
		{1023.5 * MiByte, 0, "1.0 GiB"},
		{1023.5*GiByte - 1, 0, "1023 GiB"},
		{1023.5 * GiByte, 0, "1.0 TiB"},
		{1023.5*TiByte - 1, 0, "1023 TiB"},
		{1023.5 * TiByte, 0, "1.0 PiB"},
		// Above 2^53 float64(s) rounds: this threshold is measured.
		{1_152_358_554_653_425_599, 0, "1023 PiB"},
		{1_152_358_554_653_425_600, 0, "1.0 EiB"},
		{1_048_575, 3, "1.00 MiB"},
	}
	for _, c := range cases {
		got := IBytes(c.in)
		if c.n != 0 {
			got = IBytesN(c.in, c.n)
		}
		if got != c.want {
			t.Errorf("IBytes(%d) n=%d: got %s, want %s", c.in, c.n, got, c.want)
		}
		if err := roundTripError(got, new(big.Int).SetUint64(c.in), parseBytesAsBig); err != nil {
			t.Errorf("IBytes(%d) n=%d: %v", c.in, c.n, err)
		}
	}
}

func TestBytesNUnitPromotion(t *testing.T) {
	cases := []struct {
		in   uint64
		n    int
		next uint64 // the larger unit the input is promoted to, 0 if it is not
		want string
	}{
		{999_499, 3, 0, "999 kB"},
		{999_500, 3, MByte, "1.00 MB"},
		{999_999, 3, MByte, "1.00 MB"},
		{999_499_999, 3, 0, "999 MB"},
		{999_500_000, 3, GByte, "1.00 GB"},
		{999_499_999_999, 3, 0, "999 GB"},
		{999_500_000_000, 3, TByte, "1.00 TB"},
		{999_499_999_999_999, 3, 0, "999 TB"},
		{999_500_000_000_000, 3, PByte, "1.00 PB"},
		{999_499_999_999_999_935, 3, 0, "999 PB"},
		{999_499_999_999_999_936, 3, EByte, "1.00 EB"},

		{999_949, 4, 0, "999.9 kB"},
		{999_950, 4, MByte, "1.000 MB"},
		{999_949_999, 4, 0, "999.9 MB"},
		{999_950_000, 4, GByte, "1.000 GB"},
		{999_949_999_999, 4, 0, "999.9 GB"},
		{999_950_000_000, 4, TByte, "1.000 TB"},
		{999_949_999_999_999, 4, 0, "999.9 TB"},
		{999_950_000_000_000, 4, PByte, "1.000 PB"},
		// Above 2^53 float64(s) rounds: this threshold is measured.
		{999_949_999_999_999_935, 4, 0, "999.9 PB"},
		{999_949_999_999_999_936, 4, EByte, "1.000 EB"},

		{999_500, 0, MByte, "1 MB"},
		{999_500, 1, MByte, "1 MB"},
		{999_500, 2, MByte, "1.0 MB"},
		{999_500, -1, MByte, "1 MB"},
		{999_999, 0, MByte, "1 MB"},
		{999_999, 8, 0, "999.99900 kB"},
		{9, 3, 0, "9 B"},
	}
	for _, c := range cases {
		got := BytesN(c.in, c.n)
		if got != c.want {
			t.Errorf("BytesN(%d, %d): got %s, want %s", c.in, c.n, got, c.want)
		}
		if c.next != 0 {
			if unit := BytesN(c.next, c.n); got != unit {
				t.Errorf("BytesN(%d, %d): got %s, want %s as BytesN(%d, %d)", c.in, c.n, got, unit, c.next, c.n)
			}
		}
		if err := roundTripError(got, new(big.Int).SetUint64(c.in), parseBytesAsBig); err != nil {
			t.Errorf("BytesN(%d, %d): %v", c.in, c.n, err)
		}
	}
}

